```python
import sys

# Global modulus
MOD = 0

def egcd(a, b):
    """Extended Euclidean algorithm. Returns (g, x, y) such that a*x + b*y = g = gcd(a,b)."""
    if b == 0:
        return a, 1, 0
    g, x1, y1 = egcd(b, a % b)
    x = y1
    y = x1 - (a // b) * y1
    return g, x, y

def modInv(a, m):
    """Modular inverse of a modulo m. Assumes gcd(a,m)=1."""
    g, x, y = egcd(a, m)
    assert g == 1
    if x < 0:
        x += m
    return x

class Mint:
    """Modular integer class with global modulus MOD."""
    __slots__ = ('value',)

    def __init__(self, x=0):
        if isinstance(x, Mint):
            self.value = x.value
        else:
            self.value = x % MOD
            if self.value < 0:
                self.value += MOD

    def __add__(self, other):
        if isinstance(other, Mint):
            res = self.value + other.value
        else:
            res = self.value + other
        return Mint(res)

    def __radd__(self, other):
        return self + other

    def __sub__(self, other):
        if isinstance(other, Mint):
            res = self.value - other.value
        else:
            res = self.value - other
        return Mint(res)

    def __rsub__(self, other):
        return Mint(other) - self

    def __mul__(self, other):
        if isinstance(other, Mint):
            res = self.value * other.value
        else:
            res = self.value * other
        return Mint(res)

    def __rmul__(self, other):
        return self * other

    def __truediv__(self, other):
        if isinstance(other, Mint):
            inv = modInv(other.value, MOD)
        else:
            inv = modInv(other % MOD, MOD)
        return self * Mint(inv)

    def __rtruediv__(self, other):
        return Mint(other) / self

    def __neg__(self):
        return Mint(-self.value)

    def __eq__(self, other):
        if isinstance(other, Mint):
            return self.value == other.value
        return self.value == other % MOD

    def __ne__(self, other):
        return not self.__eq__(other)

    def __lt__(self, other):
        if isinstance(other, Mint):
            return self.value < other.value
        return self.value < other

    def __le__(self, other):
        return self < other or self == other

    def __gt__(self, other):
        return not (self <= other)

    def __ge__(self, other):
        return not (self < other)

    def __repr__(self):
        return str(self.value)

    def __int__(self):
        return self.value

    def __pow__(self, exponent):
        """Modular exponentiation. exponent must be non-negative integer."""
        assert exponent >= 0
        result = Mint(1)
        base = Mint(self)
        exp = exponent
        while exp > 0:
            if exp & 1:
                result *= base
            base *= base
            exp >>= 1
        return result

def main():
    global MOD
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    MOD = int(data[2])

    # Precompute factorials and inverse factorials dynamically
    fact = [Mint(1)]
    inv_fact = [Mint(1)]

    def C(x, y):
        """Combination C(x, y) modulo MOD."""
        sz = max(x, y)
        while len(fact) < sz + 1:
            fact.append(fact[-1] * Mint(len(fact)))
            inv_fact.append(Mint(1) / fact[-1])
        if y < 0 or y > x:
            return Mint(0)
        return fact[x] * inv_fact[y] * inv_fact[x - y]

    # ptr_ways and ptr_dp for a single tree
    ptr_ways = [Mint(0)] * (m + 1)
    ptr_dp = [Mint(0)] * (m + 1)
    ptr_ways[0] = Mint(1)

    for i in range(1, m + 1):
        # First loop: compute ptr_ways[i]
        for j in range(i):
            l = j
            r = i - 1 - l
            ptr_ways[i] += ptr_ways[l] * ptr_ways[r] * C(l + r, l) * Mint(l + r + 2)

        # Second loop: compute ptr_dp[i]
        for j in range(i):
            l = j
            r = i - 1 - l
            add = (Mint(l) * (l + 1) + Mint(r) * (r + 1)) / Mint(2)
            ptr_dp[i] += ptr_ways[l] * ptr_ways[r] * C(l + r, l) * add
            ptr_dp[i] += (ptr_dp[l] * ptr_ways[r] + ptr_dp[r] * ptr_ways[l]) * C(l + r, r) * Mint(l + r + 2)

    # DP for the forest
    dp = [[Mint(0) for _ in range(m + 1)] for _ in range(n + 1)]
    ways = [[Mint(0) for _ in range(m + 1)] for _ in range(n + 1)]
    ways[0][0] = Mint(1)

    for i in range(1, n + 1):
        for s in range(0, min(m, i) + 1):
            if s == i:
                dp[i][s] = ptr_dp[s]
                ways[i][s] = ptr_ways[s]
                continue
            for d in range(1, s + 2):
                ft = dp[i - d][s + 1 - d]
                way = ways[i - d][s + 1 - d]
                add = d - 1
                ways[i][s] += way * ptr_ways[add] * C(s, add)
                dp[i][s] += (way * ptr_dp[add] + ptr_ways[add] * ft) * C(s, add)

    print(dp[n][m])

if __name__ == "__main__":
    main()
